// src/present/theme.ts
var HOUSE_ACCENT = "#b5532c";
function hexToRgb(hex) {
  const m = /^#?([0-9a-f]{6})$/i.exec(hex.trim());
  if (!m) throw new Error(`"${hex}" \xE4r ingen f\xE4rg p\xE5 formen #rrggbb`);
  const n2 = parseInt(m[1], 16);
  return [n2 >> 16 & 255, n2 >> 8 & 255, n2 & 255];
}
var rgbToHex = (c) => `#${c.map((v) => Math.round(Math.max(0, Math.min(255, v))).toString(16).padStart(2, "0")).join("")}`;
function luminance(hex) {
  const [r, g, b] = hexToRgb(hex).map((v) => {
    const s2 = v / 255;
    return s2 <= 0.03928 ? s2 / 12.92 : ((s2 + 0.055) / 1.055) ** 2.4;
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
function contrast(a, b) {
  const [x, y] = [luminance(a), luminance(b)].sort((p, q) => q - p);
  return (x + 0.05) / (y + 0.05);
}
function mix(a, b, t) {
  const p = hexToRgb(a), q = hexToRgb(b);
  return rgbToHex([0, 1, 2].map((i) => p[i] + (q[i] - p[i]) * t));
}
function textOn(bg) {
  return contrast(bg, "#ffffff") >= contrast(bg, INK) ? "#ffffff" : INK;
}
function readableAccent(accent, surface, min = 4.5) {
  const toward = luminance(surface) > 0.4 ? "#000000" : "#ffffff";
  for (let t = 0; t <= 1.0001; t += 0.05) {
    const c = mix(accent, toward, t);
    if (contrast(c, surface) >= min) return c;
  }
  return toward;
}
var INK = "#1c1b19";
function theme(brand) {
  const accent = brand?.accent ?? HOUSE_ACCENT;
  const light = {
    bg: "#f6f3f0",
    surface: "#ffffff",
    line: "#e7e1da",
    ink: INK,
    muted: "#6b655d",
    accent,
    accent_text: readableAccent(accent, "#ffffff"),
    on_accent: textOn(accent),
    accent_soft: brand?.accent_soft ?? mix(accent, "#ffffff", 0.9)
  };
  const darkSurface = "#22201d";
  const darkAccent = contrast(accent, darkSurface) >= 3 ? accent : readableAccent(accent, darkSurface, 3);
  const dark = {
    bg: "#171614",
    surface: darkSurface,
    line: "#38342f",
    ink: "#f2eee9",
    muted: "#a59d93",
    accent: darkAccent,
    accent_text: readableAccent(accent, darkSurface),
    on_accent: textOn(darkAccent),
    accent_soft: mix(accent, darkSurface, 0.82)
  };
  return { light, dark };
}
var vars = (t) => Object.entries(t).map(([k, v]) => `--${k.replace(/_/g, "-")}:${v}`).join(";");
function themeCss(t) {
  return `:root{color-scheme:light dark;${vars(t.light)}}@media (prefers-color-scheme:dark){:root{${vars(t.dark)}}}`;
}

// src/present/fonts.ts
function presentationFonts(fonts) {
  const sheets = (fonts?.stylesheets ?? []).filter((u) => /^https:\/\//.test(u));
  const faces = Object.values(fonts?.families ?? {}).filter((f) => f.style !== "italic").map((f) => ({ family: f.family, weight: f.weight ?? 400 }));
  if (!sheets.length || !faces.length) return null;
  const heading = faces.reduce((a, b) => b.weight > a.weight ? b : a);
  const same = faces.filter((f) => f.family === heading.family);
  const body = (same.length > 1 ? same : faces).reduce((a, b) => b.weight < a.weight ? b : a);
  return { stylesheets: sheets, heading, body };
}
var family = (f) => `"${f.family.replace(/["\\]/g, "")}"`;
function fontsHead(f, esc2) {
  if (!f) return "";
  return f.stylesheets.map((u) => `<link rel="stylesheet" href="${esc2(u)}">`).join("") + `<style>body{font-family:${family(f.body)},"Manrope",-apple-system,sans-serif;font-weight:${f.body.weight}}h1,h2,h3,.kicker,.tag,.num,.btn,.pill,b,strong{font-family:${family(f.heading)},"Manrope",-apple-system,sans-serif}h1,h2,h3{font-weight:${f.heading.weight}}</style>`;
}

